import React from 'react';

import { IWorkoutTrackMarkup } from '@apps/Workouts/@types/workoutTrackMarkup.types';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput from '@ui-kit/Input';
import { showModal } from '@ui-kit/Modal';

interface IWorkoutTrackMarkupEditModalProps {
  onClose?: () => void;
  markup: IWorkoutTrackMarkup;
  onSave: (markup: IWorkoutTrackMarkup) => void;
}

const WorkoutTrackMarkupEditModal: React.FC<IWorkoutTrackMarkupEditModalProps> = ({
  markup,
  onSave,
}) => {
  const [name, setName] = React.useState(markup.name);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        onSave({ ...markup, name });
      }}
    >
      <PohInput value={name} onChange={setName} required label="Название" autoFocus />
      <div className="mb-n3 mt-3 text-end">
        <PohButton type="submit" variant={ButtonVariant.Success}>
          Сохранить
        </PohButton>
      </div>
    </form>
  );
};

export const editWorkoutTrackMarkupInModalAsync = (
  markup: IWorkoutTrackMarkup,
  title = '',
): Promise<IWorkoutTrackMarkup> => {
  return new Promise((res) => {
    showModal({
      title,
      children: (clos) => (
        <WorkoutTrackMarkupEditModal
          onSave={(up) => {
            res(up);
            clos();
          }}
          markup={markup}
        />
      ),
    });
  });
};
